        con.commit()
        con.close()
        rows = self.rows_for(OpenCodeParser(), self.DATABASE)
        self.assertEqual(
            [row.text for row in rows if row.text.startswith("parser:")],
            ["parser: unparseable record %d (message.data: not a JSON object): [1]" % rowid],
        )

