    def test_bad_payload_is_reported_not_fatal(self):
        import sqlite3

        con = sqlite3.connect(str(self.home / TABBY_REL))
        con.execute(
            "INSERT INTO user_events(user_id,kind,created_at,payload) VALUES(1,'view','2026-10-01 10:00:05','{\"view\":')"
        )
